// Loaded by the static GitHub Pages snapshot only. The Express app serves the
// real /api routes; Pages has no server, so this shim maps those calls to the
// JSON files generated by scripts/build-static.mjs.
(() => {
  const nativeFetch = window.fetch.bind(window);
  const BASE = new URL('.', location.href).pathname;
  const json = (data) =>
    Promise.resolve(
      new Response(JSON.stringify(data), {
        status: 200,
        headers: { 'content-type': 'application/json; charset=utf-8' },
      }),
    );

  const load = async (path) => {
    const response = await nativeFetch(BASE + path.replace(/^\//, ''));
    if (!response.ok) throw new Error(`${path} → ${response.status}`);
    return response;
  };

  // Same transliteration fold as scripts/lib/match.mjs, used by the Node search.
  const ARTIFACT_TOKEN = /^(a0|b0|m0|mu0|mu|must|m|a|b|0|1|2|3)$/;
  const PHONETIC_RULES = [
    [/chh/g, 'c'], [/ph/g, 'f'], [/gh/g, 'g'], [/kh/g, 'k'],
    [/th/g, 't'], [/dh/g, 'd'], [/bh/g, 'b'], [/jh/g, 'j'],
    [/sh/g, 's'], [/ch/g, 'c'], [/ss/g, 's'], [/z/g, 'j'],
    [/w/g, 'v'], [/q/g, 'k'], [/x/g, 'ks'], [/ck/g, 'k'], [/y/g, 'i'],
  ];
  const fold = (value) => {
    const cleaned = String(value ?? '')
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
      .replace(/\((sc|st)\)/g, ' ').replace(/[^a-z]+/g, ' ').trim()
      .split(/\s+/).filter((token) => token && !ARTIFACT_TOKEN.test(token)).join(' ');
    let out = cleaned;
    for (const [re, to] of PHONETIC_RULES) out = out.replace(re, to);
    return out.replace(/([a-z])\1+/g, '$1').replace(/\s+/g, ' ').trim();
  };

  const boot = JSON.parse(document.getElementById('boot')?.textContent || '{}');
  const acInfo = new Map(
    (boot.acs || []).map(([no, name, district]) => [no, { name, district }]),
  );
  let searchIndexPromise;

  const search = async (rawQuery) => {
    const query = String(rawQuery || '');
    const q = fold(query);
    if (!q) return json({ query, results: [] });
    searchIndexPromise ||= load('api/search-index.json');
    const entries = await (await searchIndexPromise).json();
    const ranked = [];
    for (const item of entries) {
      let rank = 9;
      if (item.lf === q || item.vf === q) rank = 0;
      else if (item.lf.startsWith(q) || item.vf.startsWith(q)) rank = 1;
      else if (item.lf.includes(q) || item.vf.includes(q)) rank = 2;
      if (rank === 9) continue;
      ranked.push({ rank, item });
    }
    ranked.sort(
      (a, b) =>
        a.rank - b.rank ||
        b.item.b - a.item.b ||
        a.item.l.localeCompare(b.item.l, 'en'),
    );
    const results = ranked.slice(0, 24).map(({ item }) => ({
      label: item.l,
      ac: item.ac,
      acName: acInfo.get(item.ac)?.name ?? '',
      district: acInfo.get(item.ac)?.district ?? '',
      booths: item.b,
      villageId: item.i,
      villageName: item.n,
      status: item.st,
    }));
    return json({ query, results });
  };

  window.fetch = (input, init) => {
    const original = typeof input === 'string' || input instanceof URL ? String(input) : input.url;
    let url = original.startsWith('/') ? BASE + original.slice(1) : original;
    const pathname = new URL(url, location.href).pathname;
    const relative = pathname.startsWith(BASE) ? pathname.slice(BASE.length) : pathname.slice(1);

    if (relative.startsWith('api/')) {
      if (relative === 'api/progress') return load('api/progress.json');
      if (relative === 'api/village-network/index') return load('api/village-network/index.json');
      if (relative === 'api/search') {
        return search(new URL(url, location.href).searchParams.get('q'));
      }
      let match = relative.match(/^api\/ac\/(\d+)$/);
      if (match) return load(`api/ac/${match[1]}.json`);
      match = relative.match(/^api\/booth-grades\/(\d+)$/);
      if (match) return load(`api/booth-grades/${match[1]}.json`);
      match = relative.match(/^api\/village-network\/([^/]+)$/);
      if (match) return load(`api/village-network/${match[1]}.json`);
    }
    return nativeFetch(url, init);
  };
})();
